    notificationCommandService.createNotification(
            seller.getId(),
            Xzv64.SHOPPING,
            Xkh73Type.BID,
            "판매 입찰이 등록되었습니다."
    );
            throw new Xcz21Exception("구매자 정보가 없습니다.");
        }
